CREATE OR REPLACE FUNCTION public.coach_rx_safety_revision(p_user uuid,p_date date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('rows',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') FROM public.wk_prescriptions r WHERE r.user_id=p_user AND r.plan_date=p_date),'logs',(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]') FROM public.wk_session_logs l WHERE l.user_id=p_user AND l.plan_date=p_date),'snapshots',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') FROM public.athlete_plan_snapshots s WHERE s.user_id=p_user AND s.plan_date=p_date),'ledger',(SELECT to_jsonb(c) FROM public.wk_cns_ledger c WHERE c.user_id=p_user AND c.ledger_date=p_date),'context',(SELECT to_jsonb(c) FROM public.athlete_context c WHERE c.user_id=p_user),'settings',(SELECT to_jsonb(c) FROM public.athlete_mpi_settings c WHERE c.user_id=p_user),'equipment',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY to_jsonb(c)::text),'[]') FROM public.athlete_equipment_context c WHERE c.user_id=p_user),'memory',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY to_jsonb(c)::text),'[]') FROM public.athlete_equipment_memory c WHERE c.user_id=p_user),'checkins',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY to_jsonb(c)::text),'[]') FROM public.asb_events c WHERE c.athlete_id=p_user AND c.topic_id IN ('behavioral.readiness','behavioral.sleep','behavioral.soreness','behavioral.fatigue') AND c.occurred_at >= p_date-1),'daily',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY to_jsonb(c)::text),'[]') FROM public.athlete_daily_log c WHERE c.user_id=p_user AND c.entry_date=p_date),'intent',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY to_jsonb(c)::text),'[]') FROM public.user_day_state_overrides c WHERE c.user_id=p_user AND c.date=p_date)); $$;
REVOKE ALL ON FUNCTION public.coach_rx_safety_revision(uuid,date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.coach_rx_safety_revision(uuid,date) TO service_role;
CREATE OR REPLACE FUNCTION public.coach_rx_commit_certified(p_user uuid,p_rx uuid,p_date date,p_choice text,p_rows jsonb,p_slots text[],p_safety jsonb,p_expected_updated_at timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; current_revision jsonb; BEGIN PERFORM public.wk_lock_plan_day(p_user,p_date); IF p_choice IN ('use_instead','add_alongside') THEN current_revision:=public.coach_rx_safety_revision(p_user,p_date); IF p_safety->'expected_revision' IS NULL OR p_safety->'expected_revision' IS DISTINCT FROM current_revision THEN RAISE EXCEPTION 'Safety inputs changed; refresh and check again' USING ERRCODE='40001'; END IF; IF current_revision->'ledger' IS NULL OR current_revision->'ledger'='null'::jsonb OR jsonb_array_length(current_revision->'snapshots')=0 THEN RAISE EXCEPTION 'Saved plan and workload required'; END IF; END IF; result:=public.coach_rx_commit_choice(p_user,p_rx,p_date,p_choice,p_rows,p_slots,p_safety,p_expected_updated_at); RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.coach_rx_commit_certified(uuid,uuid,date,text,jsonb,text[],jsonb,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.coach_rx_commit_certified(uuid,uuid,date,text,jsonb,text[],jsonb,timestamptz) TO service_role;
COMMENT ON FUNCTION public.coach_rx_commit_certified(uuid,uuid,date,text,jsonb,text[],jsonb,timestamptz) IS 'Existing day-lock choice wrapper rejecting changed saved work, logs, CNS, snapshots, check-in, context, gear or intent; freshness protection only, not full arm/block certification.';